package factories

import (
	"context"
	"deploycrate-ce/internal/storage"
	"deploycrate-ce/models"
	"encoding/json"
	"fmt"
	"time"

	"github.com/go-faker/faker/v4"
	"github.com/google/uuid"
)

// Factory declarations below are generated by Andurel.

type TokenFactory struct {
	models.TokenEntity
}

type TokenOption func(*TokenFactory)

func BuildToken(opts ...TokenOption) models.TokenEntity {
	f := &TokenFactory{
		TokenEntity: models.TokenEntity{
			Scope:     faker.Word(),
			ExpiresAt: time.Time{},
			Hash:      faker.Word(),
			MetaData:  json.RawMessage{},
		},
	}

	for _, opt := range opts {
		opt(f)
	}

	return f.TokenEntity
}

func CreateToken(ctx context.Context, exec storage.Executor, opts ...TokenOption) (models.TokenEntity, error) {
	built := BuildToken(opts...)

	entity := models.TokenEntity{
		ID:        uuid.New(),
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
		Scope:     built.Scope,
		ExpiresAt: built.ExpiresAt,
		Hash:      built.Hash,
		MetaData:  built.MetaData,
	}

	if err := exec.NewInsert().Model(&entity).Returning("*").Scan(ctx); err != nil {
		return models.TokenEntity{}, err
	}

	return entity, nil
}

func CreateTokens(ctx context.Context, exec storage.Executor, count int, opts ...TokenOption) ([]models.TokenEntity, error) {
	tokens := make([]models.TokenEntity, 0, count)

	for i := range count {
		entity, err := CreateToken(ctx, exec, opts...)
		if err != nil {
			return nil, fmt.Errorf("failed to create token %d: %w", i+1, err)
		}
		tokens = append(tokens, entity)
	}

	return tokens, nil
}

